# Gente y frases de los locales de servicio de cada ciudad (maps/_tools/personalizar_servicios.py).
# Propuesta provisional, pendiente de Javier.


def sala(persona, frases_persona, visitante=None, frases_visitante=None, placa=None, nodo="Paciente"):
    out = {nodo: (persona, frases_persona)}
    if visitante:
        out["Visitante"] = (visitante, frases_visitante)
    if placa:
        out["PlacaCiudad"] = placa
    return out


def salud(*a):
    return sala(*a, nodo="Paciente")


def tienda(*a):
    return sala(*a, nodo="Cliente")


